/// `a + b` modulo the prime with `2^256 = f`, `f < 2^62`.
#[inline(always)]
pub(super) fn pseudo_add_4(a: &[u64; 4], b: &[u64; 4], f: u64) -> [u64; 4] {
    let mut r = [0; 4];
    // SAFETY: the block reads and writes registers only.
    unsafe {
        asm!(
            "adds {x4}, {x4}, {x10}",
            "adcs {x5}, {x5}, {x11}",
            "adcs {x6}, {x6}, {x12}",
            "adcs {x7}, {x7}, {x13}",
            "csel {x16}, {x3}, xzr, cs",
            "adds {x4}, {x4}, {x16}",
            "b.cc 2f",
            "adcs {x5}, {x5}, xzr",
            "adcs {x6}, {x6}, xzr",
            "adcs {x7}, {x7}, xzr",
            "csel {x16}, {x3}, xzr, cs",
            "add {x4}, {x4}, {x16}",
            "2:",
            x3 = in(reg) f,
            x4 = inout(reg) a[0] => r[0],
            x5 = inout(reg) a[1] => r[1],
            x6 = inout(reg) a[2] => r[2],
            x7 = inout(reg) a[3] => r[3],
            x10 = in(reg) b[0],
            x11 = in(reg) b[1],
            x12 = in(reg) b[2],
            x13 = in(reg) b[3],
            x16 = out(reg) _,
            options(pure, nomem, nostack),
        );
    }
    r
}

